create table public.events (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,project_id uuid references public.projects(id) on delete set null,title text not null check(char_length(title) between 3 and 180),description text,event_type text not null default 'community' check(event_type in('community','workshop','livestream','podcast','lan','meetup','tournament','partner','charity','other')),status text not null default 'idea' check(status in('idea','planning','confirmed','production','live','aftercare','completed','cancelled','archived')),priority public.priority_level not null default 'normal',owner_id uuid references public.profiles(id) on delete set null,start_at timestamptz,end_at timestamptz,location text,is_online boolean not null default false,role_besc text not null default 'organizer' check(role_besc in('organizer','partner','promoter','participant')),drive_url text,eventbrite_url text,stream_url text,expected_attendees integer check(expected_attendees is null or expected_attendees>=0),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,check(end_at is null or start_at is null or end_at>=start_at));
alter table public.events enable row level security;grant select,insert,update,delete on public.events to authenticated;
create policy "members read events" on public.events for select to authenticated using(private.is_active_member(organization_id));create policy "managers create events" on public.events for insert to authenticated with check(private.is_org_manager(organization_id));create policy "managers update events" on public.events for update to authenticated using(private.is_org_manager(organization_id)) with check(private.is_org_manager(organization_id));create policy "managers delete events" on public.events for delete to authenticated using(private.is_org_manager(organization_id));
create index events_org_start_idx on public.events(organization_id,start_at,status) where deleted_at is null;create index events_project_idx on public.events(project_id) where deleted_at is null;
alter table public.migration_source_links drop constraint migration_source_links_target_table_check;alter table public.migration_source_links add constraint migration_source_links_target_table_check check(target_table in('projects','inbox_items','tasks','legacy_records','content_items','events'));
alter table public.legacy_records drop constraint legacy_records_conversion_complete;alter table public.legacy_records add constraint legacy_records_conversion_complete check((converted_target_table is null and converted_target_id is null and converted_at is null)or(converted_target_table in('inbox_items','tasks','projects','content_items','events') and converted_target_id is not null and converted_at is not null));
create function public.convert_legacy_event(p_record_id uuid,p_title text,p_description text default null,p_priority public.priority_level default 'normal',p_project_id uuid default null) returns uuid language plpgsql security invoker set search_path='' as $$ declare legacy public.legacy_records%rowtype;source_link public.migration_source_links%rowtype;new_id uuid;begin select * into legacy from public.legacy_records where id=p_record_id and deleted_at is null for update;if not found or not private.is_org_manager(legacy.organization_id) or legacy.converted_target_id is not null then raise exception 'record unavailable';end if;if p_project_id is not null and not exists(select 1 from public.projects where id=p_project_id and organization_id=legacy.organization_id and deleted_at is null)then raise exception 'project not found';end if;insert into public.events(organization_id,project_id,title,description,priority,owner_id,created_by)values(legacy.organization_id,p_project_id,trim(p_title),nullif(trim(p_description),''),p_priority,(select auth.uid()),(select auth.uid()))returning id into new_id;select * into source_link from public.migration_source_links where target_table='legacy_records' and target_id=legacy.id limit 1;if source_link.id is not null then insert into public.migration_source_links(organization_id,source_system,source_workspace,source_board_id,source_item_id,target_table,target_id,source_url,source_payload,imported_by)values(legacy.organization_id,source_link.source_system,source_link.source_workspace,source_link.source_board_id,source_link.source_item_id,'events',new_id,source_link.source_url,source_link.source_payload,(select auth.uid()));end if;update public.legacy_records set converted_target_table='events',converted_target_id=new_id,converted_at=now(),lifecycle='completed',updated_at=now() where id=legacy.id;return new_id;end;$$;revoke all on function public.convert_legacy_event(uuid,text,text,public.priority_level,uuid) from public;grant execute on function public.convert_legacy_event(uuid,text,text,public.priority_level,uuid) to authenticated;
